from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return parity(x) for each x in xs, computed on a thread pool.

    Results are returned in input order, and the output must not
    depend on the number of worker threads used.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([0, 1, 2, 3]) == [0, 1, 0, 1]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative() -> None:
    assert parities([-3, -2, -1, 0]) == [1, 0, 1, 0]


def test_parities_preserves_order() -> None:
    xs = list(range(1000))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_independent_of_worker_count() -> None:
    xs = [7, 8, 9, -4, 0, 15, 22]
    expected = [parity(x) for x in xs]
    with ThreadPoolExecutor(max_workers=1) as pool:
        single = list(pool.map(parity, xs))
    with ThreadPoolExecutor(max_workers=8) as pool:
        many = list(pool.map(parity, xs))
    assert single == expected
    assert many == expected
    assert parities(xs) == expected


@pytest.mark.parametrize("x", [0, 1, 2, 10**12 + 1])
def test_parity_single(x: int) -> None:
    assert parity(x) == x % 2
